"use server";

import { createServerClient } from '@supabase/ssr';
import { cookies } from 'next/headers';
import { revalidatePath } from 'next/cache';

/**
 * Mendapatkan Supabase Client untuk Server Side
 */
async function getSupabase() {
  const cookieStore = await cookies();
  return createServerClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!,
    {
      cookies: {
        getAll() {
          return cookieStore.getAll();
        },
      },
    }
  );
}

/**
 * 1. Mendapatkan Statistik Dashboard PPI (Global RS)
 */
export async function getPPIDashboardStats() {
  const supabase = await getSupabase();

  const now = new Date();
  const firstDay = new Date(now.getFullYear(), now.getMonth(), 1).toISOString().split('T')[0];
  const lastDay = new Date(now.getFullYear(), now.getMonth() + 1, 0).toISOString().split('T')[0];

  const { data, error } = await supabase
    .from('surveilans_harian')
    .select(`
      *,
      master_ruangan (nama_ruangan)
    `)
    .gte('tanggal', firstDay)
    .lte('tanggal', lastDay);

  if (error || !data) {
    console.error("Error fetching PPI stats:", error);
    return null;
  }

  // Hitung HAIs Global (VAP, HAP, ISK, IAD)
  const totalHais = data.filter(r => 
    Number(r.vap) > 0 || Number(r.hap) > 0 || Number(r.isk) > 0 || Number(r.iad) > 0
  ).length;

  // Hitung Data Belum Terverifikasi
  const belumVerif = data.filter(r => r.is_verified === false).length;

  return {
    totalHais,
    belumVerif,
    totalEntries: data.length,
    data
  };
}

/**
 * 2. Mendapatkan Data Antrean Verifikasi (Data yang is_verified = false)
 */
export async function getPendingVerification() {
  const supabase = await getSupabase();

  const { data, error } = await supabase
    .from('surveilans_harian')
    .select(`
      *,
      master_ruangan (nama_ruangan)
    `)
    .eq('is_verified', false)
    .order('tanggal', { ascending: false });

  if (error) {
    console.error("Error fetching pending verification:", error);
    return [];
  }

  return data;
}

/**
 * 3. Server Action: Verifikasi Data secara Massal
 * Digunakan oleh petugas PPI untuk menyetujui banyak baris sekaligus
 */
export async function verifySurveilansBatch(ids: string[]) {
  if (!ids || ids.length === 0) return { success: false, message: "Tidak ada data dipilih" };

  const supabase = await getSupabase();

  const { error } = await supabase
    .from('surveilans_harian')
    .update({ 
      is_verified: true,
      verified_at: new Date().toISOString()
    })
    .in('id', ids);

  if (error) {
    console.error("Error during batch verification:", error);
    return { success: false, error: error.message };
  }

  // Refresh data pada halaman dashboard dan verifikasi
  revalidatePath('/dashboard/ppi');
  revalidatePath('/dashboard/ppi/verifikasi');
  
  return { success: true };
}

/**
 * 4. Mendapatkan Rekap Laporan Global (Bisa difilter Ruangan/Periode)
 */
export async function getGlobalReports(filters?: { ruangan_id?: string; startDate?: string; endDate?: string }) {
  const supabase = await getSupabase();

  let query = supabase
    .from('surveilans_harian')
    .select(`
      *,
      master_ruangan (nama_ruangan)
    `)
    .order('tanggal', { ascending: false });

  if (filters?.ruangan_id) query = query.eq('ruangan_id', filters.ruangan_id);
  if (filters?.startDate) query = query.gte('tanggal', filters.startDate);
  if (filters?.endDate) query = query.lte('tanggal', filters.endDate);

  const { data, error } = await query;

  if (error) {
    console.error("Error fetching global reports:", error);
    return [];
  }

  return data;
}