"use client";

import { useState } from "react";
import { CheckCircle2, AlertCircle, Calendar, User } from "lucide-react";
import { verifySurveilansBatch } from "@/services/ppi";
import { useRouter } from "next/navigation";

export default function TabelVerifikasi({ data }: { data: any[] }) {
  const [selectedIds, setSelectedIds] = useState<string[]>([]);
  const [isProcessing, setIsProcessing] = useState(false);
  const router = useRouter();

  const handleSelectAll = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.checked) {
      setSelectedIds(data.map((item) => item.id));
    } else {
      setSelectedIds([]);
    }
  };

  const handleSelectOne = (id: string) => {
    setSelectedIds((prev) =>
      prev.includes(id) ? prev.filter((i) => i !== id) : [...prev, id]
    );
  };

  const handleVerify = async () => {
    if (selectedIds.length === 0) return;
    
    setIsProcessing(true);
    try {
      const res = await verifySurveilansBatch(selectedIds);
      if (res.success) {
        setSelectedIds([]);
        router.refresh();
        alert(`Berhasil memverifikasi ${selectedIds.length} data.`);
      }
    } catch (error) {
      alert("Terjadi kesalahan saat verifikasi.");
    } finally {
      setIsProcessing(false);
    }
  };

  return (
    <div className="bg-white rounded-[2.5rem] border border-slate-100 shadow-sm overflow-hidden">
      <div className="p-8 border-b border-slate-50 flex flex-col md:flex-row justify-between items-center gap-4">
        <div>
          <h2 className="text-xl font-bold text-slate-800">Antrean Verifikasi</h2>
          <p className="text-sm text-slate-500 font-medium">Pilih data untuk disetujui secara massal</p>
        </div>
        <button
          onClick={handleVerify}
          disabled={selectedIds.length === 0 || isProcessing}
          className="w-full md:w-auto flex items-center justify-center gap-2 bg-emerald-600 text-white px-8 py-3.5 rounded-2xl text-xs font-bold hover:bg-emerald-700 transition-all shadow-lg shadow-emerald-100 disabled:bg-slate-200 disabled:shadow-none"
        >
          <CheckCircle2 size={18} />
          {isProcessing ? "Memproses..." : `Verifikasi ${selectedIds.length} Data`}
        </button>
      </div>

      <div className="overflow-x-auto">
        <table className="w-full text-left border-collapse">
          <thead>
            <tr className="bg-slate-50/50">
              <th className="p-6 w-10">
                <input
                  type="checkbox"
                  onChange={handleSelectAll}
                  checked={selectedIds.length === data.length && data.length > 0}
                  className="w-4 h-4 rounded border-slate-300 text-blue-600 focus:ring-blue-500"
                />
              </th>
              <th className="p-6 text-[10px] font-black text-slate-400 uppercase tracking-widest">Info Pasien</th>
              <th className="p-6 text-[10px] font-black text-slate-400 uppercase tracking-widest">Unit / Ruangan</th>
              <th className="p-6 text-[10px] font-black text-slate-400 uppercase tracking-widest text-center">Tindakan</th>
              <th className="p-6 text-[10px] font-black text-slate-400 uppercase tracking-widest text-center text-red-500">HAIs</th>
              <th className="p-6 text-[10px] font-black text-slate-400 uppercase tracking-widest text-center">Status</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-50">
            {data.length === 0 ? (
              <tr>
                <td colSpan={6} className="p-12 text-center text-slate-400 font-medium italic">
                  Tidak ada data yang menunggu verifikasi.
                </td>
              </tr>
            ) : (
              data.map((row) => {
                const hasHais = Number(row.vap) > 0 || Number(row.hap) > 0 || Number(row.isk) > 0 || Number(row.iad) > 0;
                return (
                  <tr key={row.id} className="hover:bg-slate-50/50 transition-colors group">
                    <td className="p-6">
                      <input
                        type="checkbox"
                        checked={selectedIds.includes(row.id)}
                        onChange={() => handleSelectOne(row.id)}
                        className="w-4 h-4 rounded border-slate-300 text-blue-600 focus:ring-blue-500"
                      />
                    </td>
                    <td className="p-6">
                      <div className="flex flex-col">
                        <span className="text-sm font-bold text-slate-700">{row.nama_pasien}</span>
                        <span className="text-[10px] text-slate-400 flex items-center gap-1 mt-1">
                          <Calendar size={10} /> {new Date(row.tanggal).toLocaleDateString('id-ID')}
                        </span>
                      </div>
                    </td>
                    <td className="p-6 text-sm font-bold text-slate-600">
                      <div className="flex items-center gap-2">
                        <span className="w-2 h-2 bg-blue-500 rounded-full"></span>
                        {row.master_ruangan?.nama_ruangan}
                      </div>
                    </td>
                    <td className="p-6 text-center">
                      <span className="text-xs font-bold text-slate-500">
                        {Number(row.uc) + Number(row.cvl) + Number(row.ivl) + Number(row.ett)} Hari
                      </span>
                    </td>
                    <td className="p-6 text-center">
                      {hasHais ? (
                        <span className="px-3 py-1 bg-red-50 text-red-600 rounded-lg text-[10px] font-black uppercase">Ada Temuan</span>
                      ) : (
                        <span className="text-slate-300 text-[10px] font-bold">Nihil</span>
                      )}
                    </td>
                    <td className="p-6 text-center">
                      <div className="flex items-center justify-center gap-1 text-amber-500 font-bold text-[10px] uppercase">
                        <AlertCircle size={14} /> Pending
                      </div>
                    </td>
                  </tr>
                );
              })
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
}